CREATE TABLE IF NOT EXISTS uploaded_assets (id char(36) PRIMARY KEY DEFAULT (UUID()), mime_type varchar(30) NOT NULL CHECK(mime_type IN ('image/jpeg','image/png','image/webp')), bytes mediumblob NOT NULL, uploaded_by char(36) NOT NULL, created_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY (uploaded_by) REFERENCES users(id), CHECK(octet_length(bytes)<=2097152)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
